<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\AviatorStatus;
use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string $licence_type
 * @property string $licence_number
 * @property string|null $licence_last4
 * @property string $issuing_authority
 * @property string|null $job_title
 * @property string|null $organisation
 * @property array|null $type_ratings
 * @property string|null $licence_media_id
 * @property AviatorStatus $status
 * @property string|null $rejection_reason
 * @property string|null $reviewed_by
 * @property Carbon|null $submitted_at
 * @property Carbon|null $verified_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class AviatorCredential extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'avc';

    protected $fillable = [
        'user_id', 'licence_type', 'licence_number', 'licence_last4', 'issuing_authority', 'job_title',
        'organisation', 'type_ratings', 'licence_media_id', 'status', 'rejection_reason', 'reviewed_by',
        'submitted_at', 'verified_at',
    ];

    protected function casts(): array
    {
        return [
            'licence_number' => 'encrypted',
            'type_ratings' => 'array',
            'status' => AviatorStatus::class,
            'submitted_at' => 'datetime',
            'verified_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** @return BelongsTo<Media, $this> */
    public function licence(): BelongsTo
    {
        return $this->belongsTo(Media::class, 'licence_media_id');
    }
}
